<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class ReservationBelonging extends Model { protected $guarded=[]; protected $casts=["medications"=>"array","accessories"=>"array","check_in_photos"=>"array","check_out_photos"=>"array","checked_in_at"=>"datetime","checked_out_at"=>"datetime","check_in_signature"=>"encrypted","check_out_signature"=>"encrypted"]; public function reservation(){return $this->belongsTo(Reservation::class);} public function hotel(){return $this->belongsTo(Hotel::class);} public function pet(){return $this->belongsTo(Pet::class);} }